/**
 * Imports a loosely laid-out sprite sheet (e.g. one generated by ChatGPT) into this game's format.
 *
 *   npm run import-sheet -- <image> <fighter-id> [--form] [--cell 128] [--copy-to <folder>]
 *
 * --form installs it as the sheet used while the fighter is transformed (fighters/<id>/form/).
 *
 * The image needs one row of frames per animation, in order: idle, run, cast, hit, ko — all facing
 * right, no text. Frames don't have to sit on an exact grid. The tool:
 *   1. removes the background (already-transparent, or a flat colour flood-filled from the edges),
 *   2. finds each sprite and groups sprites into rows,
 *   3. scales every frame by one shared factor and puts it in an equal-size cell, feet on a common baseline,
 *   4. writes public/assets/fighters/<id>/{sheet.png, sheet.json, portrait.png}.
 */
import { copyFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { basename, extname, join } from 'node:path';
import sharp, { type OverlayOptions } from 'sharp';
import { ANIMS, type SheetConfig } from '../src/game/assets';

/** Pixels fainter than this are treated as background (AI images often leave faint noise). */
const ALPHA_CUTOFF = 64;
/** Colour distance from the background colour that still counts as background. */
const BG_TOLERANCE = 40;
/** Pieces smaller than this fraction of the image are noise unless they touch a sprite. */
const MIN_AREA_FRACTION = 0.0004;
/** Detached bits (a hand, a hair spike) within this many pixels of a sprite belong to it. */
const MERGE_DISTANCE = 8;
/** Standing character height as a fraction of the cell, and where the feet sit (matches the 64px spec: 48/64, 56/64). */
const CHARACTER_HEIGHT = 0.75;
const FEET = 0.875;
const PORTRAIT_SIZE = 128;

interface Box {
  left: number;
  top: number;
  right: number;
  bottom: number;
  area: number;
  /** Sum of x over opaque pixels, for the centre of mass. */
  sumX: number;
  /** Component labels that make up this sprite. */
  ids: number[];
}

const width = (b: Box) => b.right - b.left + 1;
const height = (b: Box) => b.bottom - b.top + 1;

function parseArgs(argv: string[]) {
  const positional: string[] = [];
  const opts: Record<string, string> = {};
  let form = false;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--form') form = true;
    else if (argv[i].startsWith('--')) opts[argv[i].slice(2)] = argv[++i];
    else positional.push(argv[i]);
  }
  return { input: positional[0], id: positional[1], form, cell: Number(opts.cell ?? 128), copyTo: opts['copy-to'] };
}

/** Makes the background transparent in place. */
function removeBackground(data: Buffer, w: number, h: number): string {
  const at = (x: number, y: number) => (y * w + x) * 4;
  const corners = [at(0, 0), at(w - 1, 0), at(0, h - 1), at(w - 1, h - 1)];
  const transparentBg = corners.filter((i) => data[i + 3] < ALPHA_CUTOFF).length >= 3;

  if (!transparentBg) {
    // Flat background: flood-fill from every edge pixel that matches the corner colour, so light
    // colours inside the character (highlights, white hair) are kept.
    const bg = [0, 1, 2].map((c) => corners.reduce((s, i) => s + data[i + c], 0) / corners.length);
    const isBg = (i: number) => Math.hypot(data[i] - bg[0], data[i + 1] - bg[1], data[i + 2] - bg[2]) < BG_TOLERANCE;
    const seen = new Uint8Array(w * h);
    const stack: number[] = [];
    for (let x = 0; x < w; x++) stack.push(x, (h - 1) * w + x);
    for (let y = 0; y < h; y++) stack.push(y * w, y * w + w - 1);
    while (stack.length) {
      const p = stack.pop()!;
      if (seen[p] || !isBg(p * 4)) continue;
      seen[p] = 1;
      data[p * 4 + 3] = 0;
      const x = p % w;
      if (x > 0) stack.push(p - 1);
      if (x < w - 1) stack.push(p + 1);
      if (p >= w) stack.push(p - w);
      if (p < w * (h - 1)) stack.push(p + w);
    }
  }
  for (let i = 3; i < data.length; i += 4) if (data[i] < ALPHA_CUTOFF) data[i] = 0;
  return transparentBg ? 'already transparent' : 'flat colour, removed';
}

/** 8-connected opaque regions. */
function findComponents(data: Buffer, w: number, h: number): { boxes: Box[]; label: Int32Array } {
  const label = new Int32Array(w * h).fill(-1);
  const boxes: Box[] = [];
  const stack: number[] = [];
  for (let start = 0; start < w * h; start++) {
    if (label[start] !== -1 || data[start * 4 + 3] === 0) continue;
    const box: Box = { left: w, top: h, right: 0, bottom: 0, area: 0, sumX: 0, ids: [boxes.length] };
    label[start] = boxes.length;
    stack.push(start);
    while (stack.length) {
      const p = stack.pop()!;
      const x = p % w;
      const y = (p - x) / w;
      box.left = Math.min(box.left, x);
      box.right = Math.max(box.right, x);
      box.top = Math.min(box.top, y);
      box.bottom = Math.max(box.bottom, y);
      box.area++;
      box.sumX += x;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const nx = x + dx;
          const ny = y + dy;
          if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
          const q = ny * w + nx;
          if (label[q] === -1 && data[q * 4 + 3] !== 0) {
            label[q] = boxes.length;
            stack.push(q);
          }
        }
      }
    }
    boxes.push(box);
  }
  return { boxes, label };
}

/** How much of the smaller box lies inside the larger one (0-1). Neighbouring frames that merely touch score ~0. */
function overlapFraction(a: Box, b: Box): number {
  const ow = Math.min(a.right, b.right) - Math.max(a.left, b.left) + 1;
  const oh = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top) + 1;
  if (ow <= 0 || oh <= 0) return 0;
  return (ow * oh) / Math.min(width(a) * height(a), width(b) * height(b));
}

function merge(a: Box, b: Box): Box {
  return {
    left: Math.min(a.left, b.left),
    top: Math.min(a.top, b.top),
    right: Math.max(a.right, b.right),
    bottom: Math.max(a.bottom, b.bottom),
    area: a.area + b.area,
    sumX: a.sumX + b.sumX,
    ids: [...a.ids, ...b.ids],
  };
}

/** Big pieces become sprites; small pieces join a nearby sprite or are dropped as noise. */
function toSprites(components: Box[], minArea: number): { sprites: Box[]; dropped: number } {
  let sprites = components.filter((c) => c.area >= minArea);
  // Large pieces that mostly overlap are one sprite (e.g. hair split from the body by an outline gap).
  // Done before attaching specks, so a speck can never bridge two neighbouring frames.
  for (let changed = true; changed; ) {
    changed = false;
    outer: for (let i = 0; i < sprites.length; i++) {
      for (let j = i + 1; j < sprites.length; j++) {
        if (overlapFraction(sprites[i], sprites[j]) > 0.5) {
          sprites[i] = merge(sprites[i], sprites[j]);
          sprites = sprites.filter((_, k) => k !== j);
          changed = true;
          break outer;
        }
      }
    }
  }
  let dropped = 0;
  const gapBetween = (a: Box, b: Box) =>
    Math.max(0, a.left - b.right, b.left - a.right) + Math.max(0, a.top - b.bottom, b.top - a.bottom);
  for (const c of components.filter((c) => c.area < minArea)) {
    let best = -1;
    for (let i = 0; i < sprites.length; i++) {
      if (gapBetween(sprites[i], c) <= MERGE_DISTANCE && (best < 0 || gapBetween(sprites[i], c) < gapBetween(sprites[best], c))) best = i;
    }
    if (best >= 0) sprites[best] = merge(sprites[best], c);
    else dropped++;
  }
  return { sprites, dropped };
}

/** Groups sprites into rows by vertical overlap, top to bottom, each row left to right. */
function toRows(sprites: Box[]): Box[][] {
  const rows: { top: number; bottom: number; items: Box[] }[] = [];
  for (const s of [...sprites].sort((a, b) => a.top - b.top)) {
    const row = rows.find((r) => {
      const overlap = Math.min(r.bottom, s.bottom) - Math.max(r.top, s.top);
      return overlap >= 0.4 * Math.min(r.bottom - r.top, height(s));
    });
    if (row) {
      row.items.push(s);
      row.top = Math.min(row.top, s.top);
      row.bottom = Math.max(row.bottom, s.bottom);
    } else rows.push({ top: s.top, bottom: s.bottom, items: [s] });
  }
  return rows.sort((a, b) => a.top - b.top).map((r) => r.items.sort((a, b) => a.left - b.left));
}

async function main(): Promise<void> {
  const { input, id, form, cell, copyTo } = parseArgs(process.argv.slice(2));
  if (!input || !id || !/^[a-z0-9_-]+$/.test(id) || !(cell >= 32)) {
    console.error('Usage: npm run import-sheet -- <image> <fighter-id> [--form] [--cell 128] [--copy-to <folder>]');
    process.exit(1);
  }

  const { data, info } = await sharp(input).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { width: w, height: h } = info;
  const bgNote = removeBackground(data, w, h);
  const { boxes, label } = findComponents(data, w, h);
  const { sprites, dropped } = toSprites(boxes, w * h * MIN_AREA_FRACTION);
  const rows = toRows(sprites);

  // Sheets with no separate hit row (hit and ko merged into one row of falling frames): reuse the first two ko frames as hit.
  if (rows.length === ANIMS.length - 1) {
    rows.splice(ANIMS.indexOf('hit'), 0, rows[ANIMS.indexOf('hit')].slice(0, 2));
    console.log('Only 4 rows found: using the first 2 frames of the last row as the hit animation too.');
  }

  if (rows.length !== ANIMS.length) {
    console.error(`Found ${rows.length} rows, expected ${ANIMS.length} (${ANIMS.join(', ')}).`);
    rows.forEach((r, i) => console.error(`  row ${i + 1}: ${r.length} sprite(s), y ${r[0].top}-${Math.max(...r.map((s) => s.bottom))}`));
    process.exit(1);
  }

  // One scale for every frame, from the median standing (idle) height, so size never jumps between frames.
  const idleHeights = rows[0].map(height).sort((a, b) => a - b);
  let scale = (cell * CHARACTER_HEIGHT) / idleHeights[Math.floor(idleHeights.length / 2)];
  const widest = Math.max(...sprites.map(width));
  const tallest = Math.max(...sprites.map(height));
  scale = Math.min(scale, (cell * 0.95) / widest, (cell * FEET) / tallest);

  const source = sharp(data, { raw: { width: w, height: h, channels: 4 } });
  const columns = Math.max(...rows.map((r) => r.length));
  const layers: OverlayOptions[] = [];
  for (const [r, row] of rows.entries()) {
    for (const [c, s] of row.entries()) {
      const sw = Math.max(1, Math.round(width(s) * scale));
      const sh = Math.max(1, Math.round(height(s) * scale));
      // Keep only this sprite's own pixels, so a neighbouring sprite that overlaps its box doesn't bleed in.
      const own = new Set(s.ids);
      const piece = Buffer.alloc(width(s) * height(s) * 4);
      for (let y = 0; y < height(s); y++) {
        for (let x = 0; x < width(s); x++) {
          const from = (s.top + y) * w + s.left + x;
          if (own.has(label[from])) data.copy(piece, (y * width(s) + x) * 4, from * 4, from * 4 + 4);
        }
      }
      const frame = await sharp(piece, { raw: { width: width(s), height: height(s), channels: 4 } })
        .resize(sw, sh, { kernel: 'lanczos3' })
        .png()
        .toBuffer();
      // Centre on the centre of mass (steadier than the bounding box when limbs swing), feet on the baseline.
      const massX = (s.sumX / s.area - s.left) * scale;
      const left = Math.round(c * cell + cell / 2 - massX);
      layers.push({
        input: frame,
        left: Math.min(Math.max(c * cell, left), c * cell + cell - sw),
        top: Math.round(r * cell + cell * FEET - sh),
      });
    }
  }

  const dir = join(import.meta.dirname, '..', 'public', 'assets', 'fighters', id, ...(form ? ['form'] : []));
  mkdirSync(dir, { recursive: true });
  await sharp({ create: { width: columns * cell, height: ANIMS.length * cell, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } })
    .composite(layers)
    .png({ compressionLevel: 9 })
    .toFile(join(dir, 'sheet.png'));
  const config: SheetConfig = {
    frameWidth: cell,
    frameHeight: cell,
    frames: Object.fromEntries(ANIMS.map((a, i) => [a, rows[i].length])),
  };
  writeFileSync(join(dir, 'sheet.json'), JSON.stringify(config, null, 2) + '\n');

  // Portrait: a square around the head of the first idle frame, from the full-resolution source.
  const first = rows[0][0];
  const side = Math.min(width(first), Math.round(height(first) * 0.62));
  const centre = Math.round(first.sumX / first.area);
  await source
    .clone()
    .extract({ left: Math.max(0, Math.min(w - side, centre - Math.round(side / 2))), top: first.top, width: side, height: side })
    .resize(PORTRAIT_SIZE, PORTRAIT_SIZE, { kernel: 'lanczos3' })
    .png()
    .toFile(join(dir, 'portrait.png'));

  console.log(`Imported ${basename(input)} as "${id}"${form ? ' (transformed form)' : ''} (${cell}px cells, scale ${scale.toFixed(3)}, background ${bgNote}):`);
  ANIMS.forEach((a, i) => console.log(`  ${a.padEnd(5)} ${rows[i].length} frame(s)`));
  if (dropped) console.log(`  dropped ${dropped} speck(s) of noise`);
  console.log(`Wrote ${dir}\\{sheet.png, sheet.json, portrait.png}`);

  if (copyTo) {
    mkdirSync(copyTo, { recursive: true });
    const prefix = form ? `${id}-form` : id;
    for (const f of ['sheet.png', 'sheet.json', 'portrait.png']) copyFileSync(join(dir, f), join(copyTo, `${prefix}-${f}`));
    copyFileSync(input, join(copyTo, `${prefix}-source${extname(input)}`));
    console.log(`Copied to ${copyTo}`);
  }
}

void main();
